callbacks.onSnapshot:
def onSnapshot(mutable context, message, indicator) {
    if (time(message.timestamp[0]) != 09:30:00.000) return
    rowCount = message.rows()
    if (date(message.timestamp[0]) > 2025.03.31) {
        for (index in 0..(rowCount - 1)) backtest::order_target(context, message, message.symbol[index], 0l, "liquidate")
        return
    }
    signal = backtest::getLastData(context, message, false)
    if (signal.rows() == 0) return
    signalCodes = symbol(string(signal.code))
    weights = take(0.0, rowCount)
    currentQuantities = take(0l, rowCount)
    for (index in 0..(rowCount - 1)) {
        signalIndex = find(signalCodes, message.symbol[index])
        if (signalIndex >= 0 && signalIndex < signal.rows()) {
            factor = signal.price_volume_factor[signalIndex]
            volatility = signal.volatility_20d[signalIndex]
            if (!isNull(factor) && factor > 0 && !isNull(volatility) && volatility > 0) weights[index] = 1.0 / volatility
        }
        position = Backtest::getPosition(context.engine, message.symbol[index], "stock")["longPosition"]
        if (count(position) > 0) currentQuantities[index] = long(position.sum())
    }
    riskSum = sum(weights)
    if (riskSum > 0) weights /= riskSum
    equity = Backtest::getAvailableCash(context.engine, "stock") + sum(double(currentQuantities) * message.lastPrice)
    targetValues = equity * weights
    for (index in 0..(rowCount - 1)) {
        if (currentQuantities[index] * message.lastPrice[index] > targetValues[index]) backtest::order_target_value(context, message, message.symbol[index], targetValues[index], "riskParitySell")
    }
    for (index in 0..(rowCount - 1)) {
        if (currentQuantities[index] * message.lastPrice[index] < targetValues[index]) backtest::order_target_value(context, message, message.symbol[index], targetValues[index], "riskParityBuy")
    }
}

